fn qweather_code_for_wmo(code: Option<u16>) -> &'static str {
    match code {
        Some(0) => "100",
        Some(1) => "103",
        Some(2) => "101",
        Some(3) => "104",
        Some(45 | 48) => "501",
        Some(51 | 53 | 55) => "309",
        Some(56 | 57 | 66 | 67) => "313",
        Some(61) => "305",
        Some(63) => "306",
        Some(65) => "307",
        Some(71) => "400",
        Some(73) => "401",
        Some(75) => "402",
        Some(77 | 85) => "407",
        Some(80 | 81) => "300",
        Some(82) => "301",
        Some(86) => "402",
        Some(95) => "302",
        Some(96 | 99) => "304",
        _ => "999",
    }
}
